//! What an instruction reads and writes: registers (its operands' and
//! implicit ones, such as NZCV and LR), memory, and control flow.
//!
//! The data is LLVM's (`tables/a64-access.txt`, generated by
//! `tools/arm64/access.py`): each encoding's LLVM record, with its
//! `(outs)` written and `(ins)` read, tied operands (writeback) both, and
//! its `Defs` and `Uses`. Where LLVM leaves something out (FPSR's
//! cumulative flags, what MSR writes, SMSTART's zeroing), the generator
//! and [`Instruction::written_registers`] add it: the write set is
//! complete, over-approximated where unsure. What a callee or an
//! exception handler does is not the instruction's: BL writes LR, not the
//! registers the callee clobbers (see [`Effects::CALL`] and
//! [`Effects::EXCEPTION`]).

use turbonop_isa::{Access as AccessKind, Bits, OtherBits, RegisterAccess};

use crate::Instruction;
use crate::tables::{REG_CLASSES, RegClass, file, flag, record, value};

/// An element size: of a vector's lanes, an SVE register's elements, or a
/// ZA tile's.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Element {
    /// 8 bits.
    B,
    /// 16 bits.
    H,
    /// 32 bits.
    S,
    /// 64 bits.
    D,
    /// 128 bits.
    Q,
}

impl Element {
    /// The size in bits.
    pub fn bits(self) -> u32 {
        8 << self as u32
    }

    /// The element by src/tables.rs's code (1 to 5 for B to Q).
    pub(crate) fn from_code(c: u8) -> Option<Element> {
        Some(match c {
            1 => Element::B,
            2 => Element::H,
            3 => Element::S,
            4 => Element::D,
            5 => Element::Q,
            _ => return None,
        })
    }

    /// The element by its letter.
    pub(crate) fn from_letter(c: u8) -> Option<Element> {
        Some(match c.to_ascii_uppercase() {
            b'B' => Element::B,
            b'H' => Element::H,
            b'S' => Element::S,
            b'D' => Element::D,
            b'Q' => Element::Q,
            _ => return None,
        })
    }
}

/// A register, as an operand names it: its file, number, and width.
///
/// Registers alias: W*n* is the low half of X*n* (and a write of W*n*
/// zeroes the upper half: it writes all of X*n*); B*n*, H*n*, S*n*,
/// D*n*, Q*n*, and V*n* are the low bits of Z*n* (and a write of any of
/// them zeroes the bits above it); PN*n* is P*n*; ZA's tiles are parts
/// of ZA. [`Register::id`] says which register of a [`RegisterSet`] each is part of.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Register {
    /// X0 to X30 (64-bit).
    X(u8),
    /// W0 to W30 (32-bit).
    W(u8),
    /// The stack pointer (64-bit).
    Sp,
    /// The stack pointer's low 32 bits.
    Wsp,
    /// The 64-bit zero register: reads as zero, writes are discarded.
    Xzr,
    /// The 32-bit zero register.
    Wzr,
    /// B0 to B31: 8-bit scalar SIMD&FP registers.
    B(u8),
    /// H0 to H31 (16-bit).
    H(u8),
    /// S0 to S31 (32-bit).
    S(u8),
    /// D0 to D31 (64-bit).
    D(u8),
    /// Q0 to Q31 (128-bit).
    Q(u8),
    /// V0 to V31, as a vector (its operand's arrangement says how much
    /// of it). In a [`RegisterSet`], all of V*n* and Z*n*.
    V(u8),
    /// Z0 to Z31: SVE vectors (V*n* is the low 128 bits of each).
    Z(u8),
    /// P0 to P15: SVE predicates.
    P(u8),
    /// PN0 to PN15: predicates as counters (P*n*).
    Pn(u8),
    /// The SME ZA array.
    Za,
    /// A ZA tile, by element size and number (`ZA3.S`).
    ZaTile(Element, u8),
    /// SME2's lookup table register.
    Zt0,
    /// SVE's first-fault register.
    Ffr,
    /// The condition flags.
    Nzcv,
    /// The floating-point control register.
    Fpcr,
    /// The floating-point status register (its cumulative exception
    /// flags).
    Fpsr,
    /// The FP8 mode register.
    Fpmr,
    /// The SVE vector length (in 64-bit granules), read by RDVL, ADDVL,
    /// CNTB, ...
    Vg,
    /// SME's streaming mode and ZA enables (PSTATE.SM and PSTATE.ZA).
    Svcr,
    /// The other PSTATE fields: DAIF, PAN, UAO, DIT, SSBS, TCO, ...
    Pstate,
    /// Any other system register (TPIDR_EL0, PAR_EL1, GCSPR_EL0, ...)
    /// or system state (caches, TLBs): one register for all of them.
    SystemRegisters,
}

/// [`Register::id`]s of the special registers (after X0-X30, SP, V0-V31, and
/// P0-P15).
mod id {
    pub const SP: u8 = 31;
    pub const V: u8 = 32;
    pub const P: u8 = 64;
    pub const FFR: u8 = 80;
    pub const ZA: u8 = 81;
    pub const ZT0: u8 = 82;
    pub const NZCV: u8 = 83;
    pub const FPCR: u8 = 84;
    pub const FPSR: u8 = 85;
    pub const FPMR: u8 = 86;
    pub const VG: u8 = 87;
    pub const SVCR: u8 = 88;
    pub const PSTATE: u8 = 89;
    pub const SYSREGS: u8 = 90;
    /// One past the last.
    pub const END: u8 = 91;
}

impl Register {
    /// The register's identity, what a [`RegisterSet`] holds: X*n* and W*n*
    /// are the same register, as are SP and WSP, V*n*, Z*n* and the
    /// scalars B*n* to Q*n*, P*n* and PN*n*, and ZA and its tiles. `None`
    /// for the zero registers, and for numbers out of range.
    pub fn id(self) -> Option<u8> {
        let num = |n: u8, limit: u8, base: u8| (n < limit).then_some(base + n);
        match self {
            Register::X(n) | Register::W(n) => num(n, 31, 0),
            Register::Sp | Register::Wsp => Some(id::SP),
            Register::Xzr | Register::Wzr => None,
            Register::B(n)
            | Register::H(n)
            | Register::S(n)
            | Register::D(n)
            | Register::Q(n)
            | Register::V(n)
            | Register::Z(n) => num(n, 32, id::V),
            Register::P(n) | Register::Pn(n) => num(n, 16, id::P),
            Register::Za | Register::ZaTile(..) => Some(id::ZA),
            Register::Zt0 => Some(id::ZT0),
            Register::Ffr => Some(id::FFR),
            Register::Nzcv => Some(id::NZCV),
            Register::Fpcr => Some(id::FPCR),
            Register::Fpsr => Some(id::FPSR),
            Register::Fpmr => Some(id::FPMR),
            Register::Vg => Some(id::VG),
            Register::Svcr => Some(id::SVCR),
            Register::Pstate => Some(id::PSTATE),
            Register::SystemRegisters => Some(id::SYSREGS),
        }
    }

    /// The register a [`RegisterSet`] holds as `id`: X*n*, SP, V*n*, P*n*,
    /// ZA, and the special registers.
    pub fn from_id(id: u8) -> Option<Register> {
        Some(match id {
            0..=30 => Register::X(id),
            id::SP => Register::Sp,
            32..=63 => Register::V(id - id::V),
            64..=79 => Register::P(id - id::P),
            id::FFR => Register::Ffr,
            id::ZA => Register::Za,
            id::ZT0 => Register::Zt0,
            id::NZCV => Register::Nzcv,
            id::FPCR => Register::Fpcr,
            id::FPSR => Register::Fpsr,
            id::FPMR => Register::Fpmr,
            id::VG => Register::Vg,
            id::SVCR => Register::Svcr,
            id::PSTATE => Register::Pstate,
            id::SYSREGS => Register::SystemRegisters,
            _ => return None,
        })
    }

    /// The register's width in bits, where it has one of its own (not
    /// for V*n*, whose arrangement says, Z*n* and P*n*, whose size is the
    /// implementation's, or ZA).
    pub fn bits(self) -> Option<u32> {
        Some(match self {
            Register::X(_) | Register::Sp | Register::Xzr | Register::D(_) => 64,
            Register::W(_) | Register::Wsp | Register::Wzr | Register::S(_) => 32,
            Register::B(_) => 8,
            Register::H(_) => 16,
            Register::Q(_) => 128,
            Register::Zt0 => 512,
            Register::Nzcv
            | Register::Fpcr
            | Register::Fpsr
            | Register::Fpmr
            | Register::Vg
            | Register::Svcr => 64,
            _ => return None,
        })
    }
}

/// A set of registers, by storage ([`Register::id`]): [`turbonop_isa`]'s,
/// two words.
pub type RegisterSet = turbonop_isa::BitSet<Register, 2>;

/// A set of storages as one word of bits (what the access data holds),
/// for the work of making a [`RegisterSet`].
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub(crate) struct Storages(pub(crate) u128);

impl Storages {
    /// No registers.
    pub const EMPTY: Storages = Storages(0);

    /// Adds `r` (the zero registers are never added).
    #[inline]
    pub fn insert(&mut self, r: Register) {
        if let Some(i) = r.id() {
            self.0 |= 1 << i;
        }
    }

    /// As a [`RegisterSet`].
    #[allow(clippy::cast_possible_truncation)] // Its two halves.
    pub(crate) fn set(self) -> RegisterSet {
        RegisterSet::from_words([self.0 as u64, (self.0 >> 64) as u64])
    }

    /// Every X register, X0 to X30.
    fn all_x() -> u128 {
        (1 << 31) - 1
    }

    fn add_file(&mut self, file: u8) {
        self.0 |= match file {
            file::X | file::W => Storages::all_x(),
            file::XSP | file::WSP => Storages::all_x() | 1 << id::SP,
            file::B..=file::Z => u128::from(u32::MAX) << id::V,
            file::P | file::PN => 0xFFFF << id::P,
            file::ZA => 1 << id::ZA,
            _ => 1 << id::ZT0,
        };
    }

    /// Adds the registers of class `c` that field value `v` names (every
    /// register of its file if `v` is not valid for it: never fewer).
    fn add_class(&mut self, c: &RegClass, v: u64) {
        let Some(&first) = c.firsts.get(v as usize).filter(|&&f| f != 255) else {
            self.add_file(c.file);
            return;
        };
        for i in 0..c.count {
            let n = u32::from(first) + u32::from(i) * u32::from(c.stride);
            let bit = match c.file {
                // (31 is the zero register: nothing.)
                file::X | file::W if n >= 31 => continue,
                file::X | file::W => n,
                file::XSP | file::WSP => n.min(31),
                file::B..=file::Z => u32::from(id::V) + n % 32,
                file::P | file::PN => u32::from(id::P) + n % 16,
                file::ZA => u32::from(id::ZA),
                _ => u32::from(id::ZT0),
            };
            self.0 |= 1 << bit;
        }
    }
}

impl FromIterator<Register> for Storages {
    fn from_iter<I: IntoIterator<Item = Register>>(iter: I) -> Storages {
        let mut s = Storages::EMPTY;
        for r in iter {
            s.insert(r);
        }
        s
    }
}

/// What an instruction does besides computing registers: memory, control
/// flow, and system effects.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub(crate) struct Effects(u16);

impl Effects {
    /// It may read memory.
    pub const LOAD: Effects = Effects(1 << 0);
    /// It may write memory.
    pub const STORE: Effects = Effects(1 << 1);
    /// A call (BL, BLR, ...): it writes LR, and the callee runs.
    pub const CALL: Effects = Effects(1 << 2);
    /// A branch (conditional or not; not a call or return).
    pub const BRANCH: Effects = Effects(1 << 3);
    /// Its target is in a register.
    pub const INDIRECT: Effects = Effects(1 << 4);
    /// A return (RET, ERET, ...).
    pub const RETURN: Effects = Effects(1 << 5);
    /// Execution never continues at the next instruction (B, BR, RET,
    /// ...).
    pub const NO_FALLTHROUGH: Effects = Effects(1 << 6);
    /// It changes or depends on state beyond its registers and memory
    /// (system registers, barriers, hints, exclusive monitors): it can't
    /// be reordered or removed.
    pub const SYSTEM: Effects = Effects(1 << 7);
    /// It generates an exception (SVC, HVC, SMC, BRK, HLT, UDF, ...): a
    /// handler runs, which may change anything it chooses.
    pub const EXCEPTION: Effects = Effects(1 << 8);
    /// It may raise a floating-point exception (and so writes FPSR).
    pub const FP_EXCEPTION: Effects = Effects(1 << 9);

    /// Whether it has every effect of `other`.
    #[inline]
    pub fn contains(self, other: Effects) -> bool {
        self.0 & other.0 == other.0
    }

    /// Whether it has any effect of `other`.
    #[inline]
    pub fn intersects(self, other: Effects) -> bool {
        self.0 & other.0 != 0
    }
}

impl core::ops::BitOr for Effects {
    type Output = Effects;
    fn bitor(self, rhs: Effects) -> Effects {
        Effects(self.0 | rhs.0)
    }
}

/// The system registers whose reads and writes mean more than
/// [`Register::SystemRegisters`], by op0:op1:CRn:CRm:op2 (MRS and MSR's bits 20:5).
fn sysreg(key: u32) -> Storages {
    const fn k(op0: u32, op1: u32, crn: u32, crm: u32, op2: u32) -> u32 {
        (op0 - 2) << 14 | op1 << 11 | crn << 7 | crm << 3 | op2
    }
    let mut s = Storages::EMPTY;
    let r = match key {
        _ if key == k(3, 3, 4, 2, 0) => Register::Nzcv,
        _ if key == k(3, 3, 4, 4, 0) => Register::Fpcr,
        _ if key == k(3, 3, 4, 4, 1) => Register::Fpsr,
        _ if key == k(3, 3, 4, 4, 2) => Register::Fpmr,
        _ if key == k(3, 3, 4, 2, 2) => {
            // SVCR: changing streaming mode or ZA zeroes the vector
            // state (as SMSTART and SMSTOP do).
            s.0 |= u128::from(u32::MAX) << id::V | 0xFFFF << id::P;
            s.insert(Register::Ffr);
            s.insert(Register::Za);
            s.insert(Register::Zt0);
            Register::Svcr
        }
        // SPSel picks the stack pointer; SP_EL0 is it when SPSel is 0.
        _ if key == k(3, 0, 4, 2, 0) || key == k(3, 0, 4, 1, 0) => {
            s.insert(Register::Sp);
            Register::Pstate
        }
        // The other PSTATE fields: DAIF, CurrentEL, PAN, UAO, ALLINT, PM,
        // DIT, SSBS, TCO (op0 3, op1 0 or 3, CRn 4, CRm 2 or 3).
        _ if key >> 14 == 1
            && matches!(key >> 11 & 7, 0 | 3)
            && key >> 7 & 0xF == 4
            && matches!(key >> 3 & 0xF, 2 | 3) =>
        {
            Register::Pstate
        }
        _ => Register::SystemRegisters,
    };
    s.insert(r);
    s
}

impl Instruction {
    fn record(&self) -> &'static crate::tables::Record {
        record(usize::from(
            crate::tables::semantics(usize::from(self.encoding)).record,
        ))
    }

    /// The registers the instruction may write: its destination operands,
    /// writeback base registers, implicit ones (NZCV for ADDS, CMP, CCMP,
    /// FCMP, ...; LR for BL and BLR; FFR; FPSR for floating-point
    /// arithmetic), and for MSR, the system register (NZCV, FPCR, ...).
    /// Complete: what it may leave alone is included, never what it may
    /// write left out. A write of W*n* is a write of X*n* (it zeroes the
    /// upper half), and of S*n*, a write of Z*n*. The zero registers are
    /// never in it.
    pub fn written_registers(&self) -> RegisterSet {
        self.written_storages().set()
    }

    pub(crate) fn written_storages(&self) -> Storages {
        let rec = self.record();
        let w = self.word();
        let mut s = Storages(self.implicit_sets().1);
        for op in rec.ops {
            if op.access & 2 != 0 {
                s.add_class(&REG_CLASSES[usize::from(op.class)], value(op.bits, w));
            }
        }
        s
    }

    /// The registers it reads and writes that no operand names: its
    /// record's implicit ones, the system register MRS reads or MSR
    /// writes, and the stack pointer an MSR to SPSel picks.
    fn implicit_sets(&self) -> (u128, u128) {
        let rec = self.record();
        let w = self.word();
        let (mut r, mut wr) = (rec.uses, rec.defs);
        if rec.flags & flag::MRS != 0 {
            r |= sysreg((w >> 5) & 0x7FFF).0;
        }
        if rec.flags & flag::MSR != 0 {
            wr |= sysreg((w >> 5) & 0x7FFF).0;
        }
        // MSR (immediate) to SPSel (op1 0, op2 5) picks the stack pointer.
        if rec.flags & flag::MSRIMM != 0 && (w >> 16) & 7 == 0 && (w >> 5) & 7 == 5 {
            wr |= 1 << id::SP;
        }
        (r, wr)
    }

    /// The registers the instruction may read: its source operands,
    /// address registers, and implicit ones (NZCV for conditional
    /// instructions, FPCR for floating-point arithmetic, ...). The zero
    /// registers are never in it.
    pub fn read_registers(&self) -> RegisterSet {
        self.read_storages().set()
    }

    pub(crate) fn read_storages(&self) -> Storages {
        let rec = self.record();
        let w = self.word();
        let mut s = Storages(self.implicit_sets().0);
        for op in rec.ops {
            if op.access & 1 != 0 {
                s.add_class(&REG_CLASSES[usize::from(op.class)], value(op.bits, w));
            }
        }
        s
    }

    /// Whether it may read memory.
    #[inline]
    pub fn reads_memory(&self) -> bool {
        self.record().flags & flag::LOAD != 0
    }

    /// Whether it may write memory.
    #[inline]
    pub fn writes_memory(&self) -> bool {
        self.record().flags & flag::STORE != 0
    }

    /// Its effects besides registers: memory, control flow, and system
    /// state.
    pub(crate) fn effects(&self) -> Effects {
        let f = self.record().flags;
        let mut e = 0u16;
        for (from, to) in [
            (flag::LOAD, Effects::LOAD),
            (flag::STORE, Effects::STORE),
            (flag::CALL, Effects::CALL),
            (flag::BRANCH, Effects::BRANCH),
            (flag::INDIRECT, Effects::INDIRECT),
            (flag::RETURN, Effects::RETURN),
            (flag::BARRIER, Effects::NO_FALLTHROUGH),
            (flag::SIDE, Effects::SYSTEM),
            (flag::EXCEPTION, Effects::EXCEPTION),
            (flag::FPEXC, Effects::FP_EXCEPTION),
        ] {
            if f & from != 0 {
                e |= to.0;
            }
        }
        // (LLVM marks traps, such as UDF, as ending the block.)
        if f & flag::TRAP != 0 {
            e |= Effects::NO_FALLTHROUGH.0 | Effects::EXCEPTION.0;
        }
        Effects(e)
    }

    /// For tools: the name of the LLVM record the access data is from
    /// (`ADDSXri`).
    #[doc(hidden)]
    pub fn llvm_record(&self) -> &'static str {
        self.record().name
    }
}

#[allow(dead_code, reason = "a check of the numbering")]
const _: () = assert!(id::END <= 128);

/// The register of file `file` numbered `n`, as an access names it.
fn file_register(file: u8, n: u32) -> Register {
    let r = (n % 32) as u8;
    match file {
        file::X if n >= 31 => Register::Xzr,
        file::XSP if n >= 31 => Register::Sp,
        file::X | file::XSP => Register::X(r),
        file::W if n >= 31 => Register::Wzr,
        file::WSP if n >= 31 => Register::Wsp,
        file::W | file::WSP => Register::W(r),
        4 => Register::B(r),
        5 => Register::H(r),
        6 => Register::S(r),
        // (A 64-bit vector is D*n*'s bits; a 128-bit one, Q*n*'s.)
        7 | 9 => Register::D(r),
        8 | 10 => Register::Q(r),
        file::Z => Register::Z(r),
        file::P => Register::P((n % 16) as u8),
        file::PN => Register::Pn((n % 16) as u8),
        file::ZA => Register::Za,
        _ => Register::Zt0,
    }
}

/// The most explicit register accesses an instruction has: up to
/// [`MAX_OPERANDS`](crate::MAX_OPERANDS) operands, each a list of up to
/// four registers.
const MAX_EXPLICIT: usize = 32;

/// What a write of `r` does to the rest of its storage: every A64 write
/// of a register zeroes the bits above it (W*n*'s of X*n*, a scalar's or
/// a vector's of Z*n*), but a write of part of ZA (a tile) leaves the
/// rest of ZA.
fn rest_of(r: Register) -> OtherBits {
    match r {
        Register::ZaTile(..) | Register::Za => OtherBits::Preserved,
        _ => OtherBits::Zeroed,
    }
}

fn access_of(read: bool, write: bool) -> AccessKind {
    match (read, write) {
        (true, true) => AccessKind::READ_WRITE,
        (true, false) => AccessKind::READ,
        (false, true) => AccessKind::WRITE,
        (false, false) => AccessKind::NONE,
    }
}

/// The storages (by [`Register::id`]) in `bits`, each with how `reads` and
/// `writes` have it.
fn implicit_accesses(
    bits: u128,
    reads: u128,
    writes: u128,
    implicit: bool,
) -> impl Iterator<Item = RegisterAccess<Register>> {
    let mut left = bits;
    core::iter::from_fn(move || {
        while left != 0 {
            let id = left.trailing_zeros() as u8;
            left &= left - 1;
            let Some(register) = Register::from_id(id) else {
                continue;
            };
            let (r, w) = (reads >> id & 1 != 0, writes >> id & 1 != 0);
            return Some(RegisterAccess {
                register,
                access: access_of(r, w),
                other_bits: if w {
                    rest_of(register)
                } else {
                    OtherBits::Preserved
                },
                implicit,
            });
        }
        None
    })
}

impl Instruction {
    /// Every register the instruction reads or writes, each once (an
    /// operand's register as the operand names it: `w0`, `d1`; an
    /// implicit one, as its storage: NZCV, LR, FPCR), and how: the same
    /// registers as [`read_registers`](Instruction::read_registers) and
    /// [`written_registers`](Instruction::written_registers), each with
    /// its width and what a write does to the rest of it.
    pub fn register_accesses(&self) -> impl Iterator<Item = RegisterAccess<Register>> + use<> {
        let rec = self.record();
        let w = self.word();
        let mut explicit = [None::<RegisterAccess<Register>>; MAX_EXPLICIT];
        let mut count = 0;
        // Storages the operands read and write, and those of fields that
        // don't name a register (every register of their file, as the
        // sets have them: never fewer).
        let (mut named_r, mut named_w) = (0u128, 0u128);
        let (mut file_r, mut file_w) = (0u128, 0u128);
        for op in rec.ops {
            let (read, write) = (op.access & 1 != 0, op.access & 2 != 0);
            let c = &REG_CLASSES[usize::from(op.class)];
            let v = value(op.bits, w);
            let Some(&first) = c.firsts.get(v as usize).filter(|&&f| f != 255) else {
                let mut s = Storages::EMPTY;
                s.add_file(c.file);
                file_r |= if read { s.0 } else { 0 };
                file_w |= if write { s.0 } else { 0 };
                continue;
            };
            for i in 0..c.count {
                let register = file_register(
                    c.file,
                    u32::from(first) + u32::from(i) * u32::from(c.stride),
                );
                if let Some(id) = register.id() {
                    named_r |= u128::from(read) << id;
                    named_w |= u128::from(write) << id;
                }
                let slot = explicit[..count]
                    .iter_mut()
                    .flatten()
                    .find(|a| a.register == register);
                if let Some(a) = slot {
                    a.access = a.access.union(access_of(read, write));
                    if write {
                        a.other_bits = rest_of(register);
                    }
                } else {
                    assert!(
                        count < MAX_EXPLICIT,
                        "more register accesses than operands have"
                    );
                    explicit[count] = Some(RegisterAccess {
                        register,
                        access: access_of(read, write),
                        other_bits: if write {
                            rest_of(register)
                        } else {
                            OtherBits::Preserved
                        },
                        implicit: false,
                    });
                    count += 1;
                }
            }
        }
        // The implicit ones (what the operands don't name), and the
        // registers of fields that name none (as the sets have them).
        let (imp_r, imp_w) = self.implicit_sets();
        let (file_r, file_w) = (file_r & !named_r, file_w & !named_w);
        let (imp_r, imp_w) = (imp_r & !named_r & !file_r, imp_w & !named_w & !file_w);
        explicit
            .into_iter()
            .flatten()
            .chain(implicit_accesses(file_r | file_w, file_r, file_w, false))
            .chain(implicit_accesses(imp_r | imp_w, imp_r, imp_w, true))
    }
}

impl turbonop_isa::Register for Register {
    const STORAGE_COUNT: u16 = id::END as u16;

    #[inline]
    fn storage(self) -> Option<u16> {
        self.id().map(u16::from)
    }

    /// Its bits of its storage. Z*n*'s, P*n*'s, and ZA's sizes are the
    /// implementation's: these are the architecture's largest (2048-bit
    /// vectors). A ZA tile's bits are spread through ZA: all of ZA's
    /// (more than the tile's).
    #[inline]
    fn from_storage(s: u16) -> Option<Register> {
        u8::try_from(s).ok().and_then(Register::from_id)
    }

    fn bits(self) -> Bits {
        Bits::low(match self {
            Register::X(_) | Register::Sp | Register::Xzr | Register::D(_) => 64,
            Register::W(_) | Register::Wsp | Register::Wzr | Register::S(_) => 32,
            Register::B(_) => 8,
            Register::H(_) => 16,
            Register::Q(_) | Register::V(_) => 128,
            Register::Z(_) => 2048,
            Register::P(_) | Register::Pn(_) | Register::Ffr => 256,
            Register::Za | Register::ZaTile(..) => 2048 * 2048,
            Register::Zt0 => 512,
            Register::Nzcv
            | Register::Fpcr
            | Register::Fpsr
            | Register::Fpmr
            | Register::Vg
            | Register::Svcr
            | Register::Pstate
            | Register::SystemRegisters => 64,
        })
    }
}
